INSERT INTO editorial.articles ("slug", "title", "standfirst", "topics", "body", "cover_path", "cover_alt", "cover_w", "cover_h", "author_slug", "status", "published_at", "updated_at", "former_slugs")
VALUES
    ('asynchronous-collaboration-in-stages', 'Work that keeps moving when nobody is online', 'Most of a project happens while the other person is asleep, in a meeting or simply busy. Here is how to set up a stage so that work, questions and money keep moving without anyone waiting for a call.', ARRAY['async-collaboration', 'team-structure']::text[], '[{"id":"the-meeting-is-not-the-work","heading":"The meeting is not the work","body":[{"type":"p","content":"Freelance projects rarely fail in the work itself. They fail in the gaps between people: the question that sat unanswered over a weekend, the file that lived in somebody''s inbox, the approval that waited for a call nobody could schedule across three time zones."},{"type":"p","content":"Working asynchronously is not a compromise you make because you cannot meet. It is a way of arranging the work so that nobody has to be online at the same moment for it to move. The arrangement matters more than the tools: a project with ten chat apps and no shared place for decisions is still synchronous, because every answer depends on catching someone."},{"type":"p","content":["Projective is built around that arrangement. A project is a run of ",{"type":"strong","text":"stages"},", and each stage carries everything needed to finish it: a conversation, files, the work handed over for review, the money held for it before anyone starts and, on a larger project, a board."]}]},{"id":"give-every-stage-one-home","heading":"Give every stage one home","body":[{"type":"p","content":"The first habit of an asynchronous team is that every piece of information has exactly one place to live. When a decision might be in a chat thread, an email or a call note, everyone has to check all three before acting, and someone always misses one."},{"type":"list","items":[{"content":[{"type":"strong","text":"The stage''s room"}," holds the conversation and the decisions made in it."]},{"content":[{"type":"strong","text":"The board"}," shows how the stage is broken down and how far each part has got."]},{"content":[{"type":"strong","text":"Files"}," keeps the references, drafts and assets the stage depends on."]},{"content":[{"type":"strong","text":"Submissions"}," is where finished work is handed over and reviewed."]}]},{"type":"p","content":"A small engagement keeps it simpler still: a Task, a single deliverable for a single price, has one shared Discussion and no channel tree to navigate. The rule is the same either way. If something matters to the stage, it lives in the stage."}]},{"id":"write-for-the-reader-who-was-not-there","heading":"Write for the reader who was not there","body":[{"type":"p","content":"An asynchronous message is read hours later, by someone switching in from other work. It has to stand on its own. A useful test is whether the reader could act on it without scrolling up."},{"type":"list","ordered":true,"items":["Lead with what you need: a decision, a file, an approval.","Give the context in two sentences, not ten.","Link the ticket, file or submission you are talking about.","Say when you need an answer, and what you will do if none comes."]},{"type":"callout","tone":"tip","title":"One decision per message","body":[{"type":"p","content":"Three questions in one message tend to get one answer. Split them, and each can be answered, quoted and found again on its own."}]}]},{"id":"let-the-board-answer-the-status-question","heading":"Let the board answer the status question","body":[{"type":"p","content":"\"Where are we?\" is the most expensive question in a remote project, because it interrupts the person doing the work to report on it. Inside every stage of a one-off or pipeline project is a board where the freelancer breaks the stage into smaller steps — an initial sketch, a colour pass, the export — and moves them as they go. The client sees that progress as it happens, without asking."},{"type":"image","src":"https://placehold.co/1200x675?text=Stage+board","alt":"Placeholder for a stage board: three columns of task cards moving from to-do to done","w":1200,"h":675,"caption":"A stage''s board: the work broken into steps, visible to the client as it moves."},{"type":"p","content":"The project''s Overview does the same job one level up. It leads with what needs you — a submission to review, a stage waiting for funding — so a client opening the project after a day away starts with the one thing only they can do."}]},{"id":"hand-over-work-not-updates","heading":"Hand over work, not updates","body":[{"type":"p","content":"The most important asynchronous moment is the handover. On a deliverable stage, the freelancer works through the stage''s checklist and attaches what it asks for: files where there are files, proof of action where there are none. The client reviews the submission against that same checklist, at a time that suits them."},{"type":"p","content":"The review ends in one of two answers. Accepting the submission completes the work and releases its escrow to the freelancer, after one confirmation, because money released is released for good. Requesting a revision sends the work back with the reasons attached. Each free revision round the stage allows is counted, so both sides can see how many are left."},{"type":"quote","content":"A good handover answers the reviewer''s questions before they are asked: what was done, what was not, and what to look at first."}]},{"id":"keep-calls-for-what-needs-them","heading":"Keep calls for what needs them","body":[{"type":"p","content":"Asynchronous does not mean never talking. Some things need a conversation: a first conversation to check fit, a tangled decision with many trade-offs, a person who is stuck. Make those calls deliberate rather than habitual."},{"type":"p","content":["A ",{"type":"strong","text":"courtesy call"}," is booked straight from a freelancer''s availability page. It is free, it creates no project and moves no money, and it respects the freelancer''s own rules: the working hours they publish, a narrower call window for interruptions, buffers either side and a minimum notice period. Working windows are set in each person''s own time zone and shown to the other side in theirs."]},{"type":"p","content":"When the conversation itself is the product — advice, tutoring, a regular check-in — it is a session: booked, paid for and held in escrow like any other stage."}]},{"id":"a-checklist-for-your-next-stage","heading":"A checklist for your next stage","body":[{"type":"list","items":["Write the stage''s checklist before anyone starts, in words a reviewer can tick off.","Agree where decisions are recorded: the stage''s room, not a side channel.","Ask for the board to be kept current, and read it before asking for status.","Answer submissions within an agreed number of working days.","Book a call only when a message has failed twice."]},{"type":"p","content":["None of this needs a new tool. It needs the work to have one home, and the people in it to trust that home. For how stages fit together over a whole project, read ",{"type":"link","href":"/articles/agile-delivery-in-stages","text":"Agile without the ceremony"},"."]}]}]'::jsonb, '/test_images/banner_4.jpg', 'Illustration of a person and a cat sitting on a hillside, watching a snow-capped mountain under a starry dusk sky', 710, 488, 'projective-editorial', 'published', '2026-08-26T08:00:00Z'::timestamptz, '2026-08-26T08:00:00Z'::timestamptz, '{}'::text[]),
    ('agile-delivery-in-stages', 'Agile without the ceremony: stages as increments', 'Sprints, stand-ups and story points were designed for teams who share an office and a payroll. A stage keeps what made agile work — small increments, a clear definition of done, review before moving on — and drops the rituals that assume you do.', ARRAY['agile-delivery', 'async-collaboration']::text[], '[{"id":"what-agile-was-for","heading":"What agile was for","body":[{"type":"p","content":"Strip away the ceremonies and agile delivery rests on three ideas: deliver in small increments, agree what \"done\" means before you start, and look at the result before deciding what comes next. Everything else — the stand-up, the planning poker, the two-week sprint — is scaffolding for teams who sit together and are paid whether or not an increment lands."},{"type":"p","content":"Freelance work has a risk an employed team does not: payment. A client is exposed if they pay for work that never arrives; a freelancer is exposed if they deliver work that is never paid. So an increment for independent work has to carry its money with it. That is what a stage is."}]},{"id":"a-stage-is-an-increment","heading":"A stage is an increment","body":[{"type":"p","content":"Every stage on Projective has one objective and one category from the CREATE framework, which says what kind of increment it is:"},{"type":"table","head":["Category","The stage''s objective","For example"],"rows":[["Create","Produce an asset","UI design, code, copywriting"],["Run","Operate something over time","Server upkeep, social posting"],["Educate","Transfer knowledge","Programming tutoring, language lessons"],["Advise","Give strategic guidance","Architecture review, business strategy"],["Test","Validate quality","Bug hunting, security audits, user testing"],["Empower","Hand over and enable","Team onboarding, documentation"]],"caption":"The six CREATE categories a stage can take.","rowHeaders":true},{"type":"p","content":"The category is not a label for its own sake. It sets the stage''s baseline weight when work is shared out, and it tells everyone what evidence will prove the stage is finished: files for a design stage, a logged session for advice, a clean report for a test."}]},{"id":"pick-the-shape-of-the-work","heading":"Pick the shape of the work","body":[{"type":"p","content":"A client-architected project takes one of three shapes:"},{"type":"dl","items":[{"term":"Task","definition":"One deliverable for one price: a single stage holding a single ticket. No timeline to manage, because there is nothing to sequence."},{"term":"One-off","definition":"A finite piece of work carried through a run of milestone stages, shown on a timeline toward a single delivery."},{"term":"Pipeline","definition":"Continuous work: many tickets moving through stages on a Kanban board, for content production, maintenance or ongoing development."}]},{"type":"p","content":"Choose the smallest shape that fits. A one-off with one milestone is a Task wearing a costume, and a pipeline for three tickets is a board nobody needs."}]},{"id":"the-checklist-is-the-definition-of-done","heading":"The checklist is the definition of done","body":[{"type":"p","content":"On a deliverable stage, \"done\" is written down before work starts as the stage''s checklist. The freelancer submits against it; the client reviews against it. That single shared list removes the most common argument in freelance work, which is not about quality but about scope."},{"type":"p","content":"The number of revision rounds is part of the same agreement. When a project is created from a freelancer''s service, the stage copies that service''s free rounds and its price for an extra round, and the terms are then frozen: a later change to the listing does not reach back into work already bought."},{"type":"callout","tone":"note","body":[{"type":"p","content":"A good checklist item can be ticked by someone who was not in the room: \"Homepage hero exported at 1x and 2x\" rather than \"Hero looks good\"."}]}]},{"id":"pull-dont-push","heading":"Pull, don''t push","body":[{"type":"p","content":"On a pipeline, freelancers hired for a stage pull work from its backlog by claiming tickets. A claim locks the ticket to them, and the escrow for it is held at that moment at the latest. A claim that is parked — taken but never started — expires after a time limit (24 hours by default), and the ticket returns to the backlog with any escrow refunded to the client in full."},{"type":"p","content":["Capacity is measured, not guessed. Each ticket carries a ",{"type":"strong","text":"workload intensity"},": its category''s baseline weight multiplied by a difficulty the client sets (low, standard or high). A stage can cap how much intensity one freelancer holds at once, and every freelancer has a global cap across all their projects, so nobody can hoard a backlog they cannot finish."]},{"type":"h3","text":"When pulling is the wrong model"},{"type":"p","content":"A client can change how a stage hands out work: round robin gives the next ticket to whoever holds the least intensity, manual assignment lets the client place each ticket, and a parallel stream fans the stage''s tickets across everyone hired on it at once. The capacity caps apply on every path."}]},{"id":"review-is-where-money-moves","heading":"Review is where the money moves","body":[{"type":"p","content":"In an agile team the review is a meeting. Here it is a decision with consequences. When a client approves a pipeline ticket''s work on one stage, that stage''s escrow is released and the ticket moves to its next stage. If the next stage has Fund on arrival switched on — the default — its escrow is held straight away from the paying wallet and the freelancer is told they can start."},{"type":"image","src":"https://placehold.co/1200x675?text=Ticket+moving+between+stages","alt":"Placeholder for a diagram of one ticket moving from an approved stage into the next, with its escrow released and then held again","w":1200,"h":675,"caption":"Approval releases one stage''s money and, with Fund on arrival on, holds the next stage''s."},{"type":"p","content":"If that hold cannot be made, the approval still stands and the finished stage is still paid. The ticket simply waits in the next stage as Needs funding until the client clears it. Nobody works ahead of the money."}]},{"id":"what-you-can-drop","heading":"What you can drop","body":[{"type":"list","items":["The daily stand-up: the board already says who is doing what.","Estimation poker: the client sets each ticket''s difficulty, and the freelancer sees it before claiming.","Sprint planning: the stage plan is the plan, and each stage is funded as it starts.","The retrospective as a ritual: each review is a small one, and its outcome is money moving or work coming back."]},{"type":"p","content":["Keep the habits, drop the calendar. For the money side of the same loop, read ",{"type":"link","href":"/articles/no-hold-no-work","text":"No hold, no work"},"."]}]}]'::jsonb, '/test_images/banner_7.jpg', 'Illustration of a teal sports car parked beneath tall palm trees silhouetted against a pink and violet dusk sky', 768, 432, 'projective-editorial', 'published', '2026-09-09T08:00:00Z'::timestamptz, '2026-09-09T08:00:00Z'::timestamptz, '{}'::text[]),
    ('structuring-a-team-that-shares-fairly', 'How to structure a team that shares fairly', 'A team on Projective is a group of freelancers who take on work under one name, without forming a company or opening a joint account. The hard part is not the paperwork. It is agreeing, before the first payment, who gets what.', ARRAY['team-structure', 'value-pricing']::text[], '[{"id":"a-team-without-a-company","heading":"A team without a company","body":[{"type":"p","content":"Freelancers have always teamed up. What usually stops them is the overhead: someone has to invoice the client, hold the money and pay everyone else, and that person carries the tax, the risk and the awkward conversations. A Projective team removes that role. The team applies, is hired and is paid as one entity, and each payment is split to its members the moment it is released."},{"type":"p","content":"Starting one is deliberately light. A team needs a name and a unique @handle, and it begins as a draft. Branding, roles, the split and invitations come afterwards, from the team''s console. It can only apply for work once it is published and has at least two members, and every member with a share of its earnings must be ready to be paid — identity checked and a payout account on file — before the team is seated on a stage."}]},{"id":"decide-the-split-before-the-work","heading":"Decide the split before the work","body":[{"type":"p","content":"Money arguments inside a team almost never come from a bad split. They come from a split that was never agreed, or was agreed in a chat nobody can find. On Projective the split is a stored rule, and it is applied automatically to every release: part can go to the team''s own vault, and the rest to members'' personal wallets."},{"type":"table","head":["Template","How a release is divided","Available on"],"rows":[["Co-op","An optional vault cut, then the remainder shared equally by every member","Every team plan"],["Finder''s fee","A fixed percentage to the member who brought the work in, the remainder split","Pro Team"],["Benevolent dictator","Everything to the team vault, distributed by an admin","Pro Team"]],"caption":"The three split templates a team can choose.","rowHeaders":true},{"type":"callout","tone":"note","title":"A worked example","body":[{"type":"p","content":"A three-person co-op with a 10% vault cut completes a £2,000 stage. The 5% service fee (£100) comes off at release, leaving £1,900. The vault takes £190 and each member receives £570."}]},{"type":"p","content":"Changing the split does not rewrite history. Saving a new template retires the old one and keeps it on record, so a team always has exactly one active rule and an audit trail of every rule it has had."}]},{"id":"roles-are-permissions-not-titles","heading":"Roles are permissions, not titles","body":[{"type":"p","content":"Every team has exactly one owner. Others join as admins or members, or under custom roles the team defines. What matters about a role is not its name but what it allows: inviting people, managing the split, or committing the team to paid work."},{"type":"p","content":"That last permission deserves the most care. Only someone allowed to commit the team — the owner, an admin, or a lead the team has trusted with it — can apply for a stage on the team''s behalf. An ordinary member cannot sign everyone up for a project, however good it looks."}]},{"id":"staff-stages-not-people","heading":"Staff stages, not people","body":[{"type":"p","content":"A client builds a stage with seats, each with a role: architecture, implementation, testing. A team can take one seat as a single unit, or several, and decide internally who does what. Three patterns cover most teams:"},{"type":"list","items":[{"content":[{"type":"strong","text":"Solo stage"}," — one member owns the whole stage."]},{"content":[{"type":"strong","text":"Sequential handover"}," — one member designs, the next builds, the next tests."]},{"content":[{"type":"strong","text":"Collaborative stage"}," — several members work the same stage''s tickets in parallel."]}]},{"type":"image","src":"https://placehold.co/1200x675?text=Stage+seats","alt":"Placeholder for a stage with three seats — architecture, implementation and testing — one of them held by a team","w":1200,"h":675,"caption":"A stage staffed by seat: a team can hold one seat as a unit, or several."},{"type":"p","content":"Workload is measured per ticket, not per seat. Being seated on a stage adds nothing to anyone''s workload; the caps on how much a person may hold at once bite only when a ticket is claimed or assigned. So a team can say yes to a stage without anyone overcommitting before the work is actually handed out."}]},{"id":"when-members-change","heading":"When members change","body":[{"type":"p","content":"People leave teams. When they do, their membership is marked as left rather than deleted, so the record of what they worked on and were paid stays intact, and anyone who returns is reactivated by a new invitation rather than added twice."},{"type":"p","content":"The owner can never simply walk away: ownership moves only by transfer to another active member. And a team cannot be archived while money is still held in escrow for work it owes, so nobody can dissolve a team to escape a stage in progress."}]},{"id":"a-structure-to-start-from","heading":"A structure to start from","body":[{"type":"list","ordered":true,"items":["Start as a co-op with a small vault cut for shared costs; move to a finder''s fee only once one person is reliably bringing in the work.","Give the right to commit the team to one or two people, and say so in the team''s description.","Agree, in writing inside the team, how members choose tickets on a collaborative stage.","Make sure every member is ready to be paid before you apply for anything."]},{"type":"p","content":["How the team prices its work is the other half of fairness. ",{"type":"link","href":"/articles/price-the-outcome-not-the-hour","text":"Price the outcome, not the hour"}," covers it."]}]}]'::jsonb, '/test_images/banner_1.jpg', 'A lone tree silhouetted against a red moon, reflected in still water', 643, 360, 'projective-editorial', 'published', '2026-09-23T08:00:00Z'::timestamptz, '2026-09-23T08:00:00Z'::timestamptz, '{}'::text[]),
    ('price-the-outcome-not-the-hour', 'Price the outcome, not the hour', 'Projective has no hourly-rate field, and that is deliberate. When every stage has a price agreed before it starts, the conversation moves from how long something takes to what it is worth.', ARRAY['value-pricing', 'agile-delivery']::text[], '[{"id":"why-there-is-no-hourly-rate","heading":"Why there is no hourly rate","body":[{"type":"p","content":"An hourly rate prices the input. It rewards the slow, punishes the expert who solves in an afternoon what takes others a week, and turns every client relationship into a debate about timesheets. It also invites surveillance: if hours are what is bought, hours are what gets tracked."},{"type":"p","content":"So a Projective freelancer profile carries skills, not a rate, and the platform never charges for how much work someone can hold at once. Capacity is protected by workload caps measured on the tickets a person holds, not by a meter on their time."}]},{"id":"soft-budgets-and-hard-budgets","heading":"Soft budgets and hard budgets","body":[{"type":"p","content":["Pricing a stage happens in two steps. When a client creates a project they can set a ",{"type":"strong","text":"soft budget"}," for each stage: a public signal of what they expect to spend, which binds nobody. It anchors the conversation without ending it."]},{"type":"p","content":["The ",{"type":"strong","text":"hard budget"}," is the price both sides agree. The client proposes; the freelancer accepts, rejects or counters; the exchange continues until both say yes, and the agreed figure is what the stage''s escrow will hold. When a stage has several seats, each seat is negotiated separately and privately: a senior architect and a junior implementer on the same stage can agree very different prices without either seeing the other''s."]}]},{"id":"match-the-price-to-the-shape","heading":"Match the price to the shape of the work","body":[{"type":"table","head":["Work","What is priced","How the price is set"],"rows":[["One-off","Each stage","Negotiated, with counter-offers"],["Pipeline","A unit price per ticket in a stage","Negotiated once for the stage''s tickets"],["Session","Each session","Fixed by the provider; not negotiable"]],"caption":"How each kind of work is priced.","rowHeaders":true},{"type":"p","content":"Sessions are fixed for a reason. When the time itself is the product — advice, tutoring, a regular check-in — haggling over each slot adds friction without adding information. The provider sets a rate they can hold consistently, and the buyer can compare it like any other price."}]},{"id":"productise-what-you-repeat","heading":"Productise what you repeat","body":[{"type":"p","content":"If you sell the same kind of work again and again, stop negotiating it from scratch. A service lets the freelancer act as the architect: the stages, their checklists and their prices are set up front. When a client buys it, the project is created from that template, ready to run."},{"type":"p","content":"A productised service is also where a price becomes honest about its edges. The listing states how many revision rounds are included and what an extra round costs, and both are copied into the stage when the project is created and frozen there. A later change to the listing does not reach into work already bought."}]},{"id":"revisions-are-part-of-the-price","heading":"Revisions are part of the price","body":[{"type":"p","content":"Unlimited revisions are not generous; they are an unpriced risk. When a stage''s free rounds are used, \"Request revision\" becomes \"Buy a revision\" at the stage''s stated price. The client pays for that round before anything is sent back, its escrow is held on the ticket, and only then is the freelancer told the paid revision is funded and they can start."},{"type":"callout","tone":"tip","title":"Set the extra-round price deliberately","body":[{"type":"p","content":"A price of zero makes extra rounds free. If you set free rounds but leave the price blank, an extra round costs the stage''s own price. State the one you mean."}]}]},{"id":"price-in-your-own-currency","heading":"Price in your own currency","body":[{"type":"p","content":"Every project, service, ticket and stage is priced in its creator''s currency, and the creator is paid that exact amount in that currency. A buyer browsing in another currency sees the price converted for reading, beside the exact amount they will be charged, and the rate is captured when the money is committed so the settlement never drifts with the market afterwards."}]},{"id":"what-the-fee-is","heading":"What the fee is, and is not","body":[{"type":"p","content":"Projective charges a flat 5% service fee on each release of escrow, plus the card processor''s own costs. The fee does not shrink as your standing grows and is not bundled into any plan, so a price you quote today means the same thing next year. It is worked out in whole minor units and rounded down, and every preview uses the same rule, so the fee you are shown is the fee that is charged."},{"type":"p","content":["Pricing the outcome only works if the outcome is protected. ",{"type":"link","href":"/articles/no-hold-no-work","text":"No hold, no work"}," explains how the agreed price is held before the first hour is spent."]}]}]'::jsonb, '/test_images/banner_8.webp', 'Illustration of fried eggs drifting like planets across a deep-blue starry sky, each ringed by thin orbit lines', 1536, 1152, 'projective-editorial', 'published', '2026-10-01T08:00:00Z'::timestamptz, '2026-10-01T08:00:00Z'::timestamptz, '{}'::text[]),
    ('no-hold-no-work', 'No hold, no work: how escrow protects both sides', 'Escrow is what lets a stranger start work for you on Monday without an invoice, a deposit or a contract lawyer. Here is exactly when money is held, when it moves, and what each side can count on.', ARRAY['escrow-and-trust', 'value-pricing']::text[], '[{"id":"the-rule-in-one-line","heading":"The rule in one line","body":[{"type":"p","content":["On Projective, ",{"type":"strong","text":"no work starts on money that is not held"},". A freelancer can claim or start a ticket only once its escrow is in place. While money sits in escrow it belongs to neither side: it is held by the platform''s ledger until the work is approved, refunded or split."]},{"type":"p","content":"When the hold cannot be made — the ticket has no price, the paying wallet is short, or the payer cannot cover it — the claim is refused rather than waved through, and the ticket moves to Needs funding. It leaves every freelancer''s board until the client funds it. The client is told why and how much; the freelancer is told \"Funded — you can start\" the moment the money is held."}]},{"id":"when-money-is-held","heading":"When money is held","body":[{"type":"table","head":["Work","Escrow is held","Escrow is released"],"rows":[["Task or one-off","Up front, when the project or its first stage begins","When the client approves the deliverable"],["Pipeline ticket","When it is claimed at the latest, or earlier if the client prepays","When the client approves the ticket''s work on a stage"],["Session","When the slot is booked","24 hours after the sitting ends, unless a no-show is claimed"]],"caption":"When escrow is held and released for each kind of work.","rowHeaders":true},{"type":"p","content":"A client may prepay a ticket, or a whole stage, before anyone claims it, from their wallet or by card. That money is held at once with nobody yet to receive it; the claim names the payee without charging again. A prepaid ticket nobody ever claims is never paid out to anyone: if its stage is approved or cancelled, it is refunded in full."}]},{"id":"when-money-moves","heading":"When money moves","body":[{"type":"p","content":"Approval is the release. Accepting a submission completes the ticket and pays its escrow to the freelancer, less the 5% service fee; approving a stage pays out whatever is still held on it and closes it. Because a release is final, the product asks for one confirmation before it happens."},{"type":"p","content":"On a pipeline, approval also moves the ticket to its next stage. With Fund on arrival on, the next stage''s escrow is held straight away from the paying wallet''s current balance; if it cannot be, the approved stage is still paid and the ticket waits as Needs funding."},{"type":"image","src":"https://placehold.co/1200x675?text=Escrow+timeline","alt":"Placeholder for a timeline showing escrow held at the start of a stage, released at approval and then pending for seven days","w":1200,"h":675,"caption":"From hold to release to available: one stage''s money over time."}]},{"id":"the-seven-day-window","heading":"The seven-day window","body":[{"type":"p","content":"Money a freelancer earns — a released escrow, a team''s shares, a session payout — shows as Pending for seven days before it becomes Available to withdraw or spend. The window is a safety margin: it gives the platform time to deal with a payment that goes wrong, such as a card the payer''s bank later disputes, before earnings leave the platform. A lost card dispute is recovered from the payer''s wallet first."},{"type":"p","content":"Money you put in yourself is never held up. A top-up or card payment, a refund, a transfer and a returned payout are Available at once, so paying by card never delays work."}]},{"id":"payable-before-you-earn","heading":"Payable before you earn","body":[{"type":"p","content":"The other half of the rule protects against a quieter failure: money that can never be paid out. A freelancer must have their identity checked and a payout account verified before they can apply for paid work, accept it, claim a ticket or join a team. A team is seated only when everyone with a share of its earnings is ready to be paid."},{"type":"quote","content":"Because every earner is payable before any work is accepted, money can never be stuck in an escrow nobody is able to receive."},{"type":"p","content":"Clients, by contrast, need no verification to buy: an individual pays by card, and the wallet that records the payment is opened for them automatically."}]},{"id":"what-each-side-can-count-on","heading":"What each side can count on","body":[{"type":"h3","text":"If you are the client"},{"type":"list","items":["No money leaves escrow until you approve, or a stage is ended under terms you can see.","A claim that is parked and never started expires, and its escrow comes back to you in full.","A card payment you make is credited at once, so funding a stage never waits on the seven-day window."]},{"type":"h3","text":"If you are the freelancer"},{"type":"list","items":["You never start on unfunded work: the claim itself fails if the money is not there.","Once you are working a ticket, the client cannot drag it to another stage under you.","If you are removed from a stage mid-ticket, or a ticket you hold is deleted, its escrow is released to you in full."]},{"type":"p","content":["Sometimes a stage should stop before it is finished. ",{"type":"link","href":"/articles/ending-a-stage-early-fairly","text":"Ending a stage early, fairly"}," covers what happens to the money then."]}]}]'::jsonb, '/test_images/banner_5.jpg', 'A black-and-white mountain peak against a large orange sun, reflected in dark water', 1920, 1080, 'projective-editorial', 'published', '2026-10-08T08:00:00Z'::timestamptz, '2026-10-12T09:30:00Z'::timestamptz, '{}'::text[]),
    ('ending-a-stage-early-fairly', 'Ending a stage early, fairly', 'Not every stage should be finished. Priorities change, briefs turn out to be wrong, people get ill. A Fair Exit lets a client end a stage in the open, with a split both sides can see before anyone commits to it.', ARRAY['escrow-and-trust', 'agile-delivery']::text[], '[{"id":"stopping-is-normal","heading":"Stopping is normal","body":[{"type":"p","content":"Projects change shape. A client discovers halfway through a design stage that the product is being renamed; a pilot is cancelled; a freelancer''s circumstances change. None of this is anyone''s fault, and treating every early ending as a dispute poisons a working relationship that might otherwise continue on the next stage."},{"type":"p","content":"What makes an early ending fair is not the exact split. It is that the split is chosen in the open, from options both sides can see, and that the money moves the moment it is chosen — no invoices to chase, no refund requests to argue over."}]},{"id":"the-three-tiers","heading":"The three tiers","body":[{"type":"p","content":["The person reviewing a stage can end it from the stage''s Submissions with ",{"type":"strong","text":"End Stage (Fair Exit)"},". Before confirming, they see a preview of all three settlement tiers, computed by the same server rule that will carry it out, so the figures shown are the figures paid."]},{"type":"table","head":["Tier","Paid to the freelancer","Returned to the client"],"rows":[["25%","A quarter of each held escrow, less the 5% fee on that share","The other three quarters, fee-free"],["50%","Half of each held escrow, less the 5% fee on that share","The other half, fee-free"],["75%","Three quarters of each held escrow, less the 5% fee on that share","The remaining quarter, fee-free"]],"caption":"What each Fair Exit tier does to the money held on the stage.","rowHeaders":true},{"type":"callout","tone":"note","title":"A worked example","body":[{"type":"p","content":"A stage holds £1,000 and is ended at the 50% tier. The freelancer''s earned share is £500; the 5% fee on it is £25, so £475 reaches them. The client is refunded £500 in full — the fee is only ever charged on the share that was earned."}]},{"type":"p","content":"A team''s share is split by its own stored rule, exactly as a normal release would be. A ticket that was prepaid but never claimed comes back to the client whole, because nobody earned any of it. The stage''s remaining tickets close as cancelled, and both sides are told."}]},{"id":"choosing-a-tier-honestly","heading":"Choosing a tier honestly","body":[{"type":"p","content":"The tier is the reviewer''s choice, which makes it a judgement, not a formula. A few questions make it a fair one:"},{"type":"list","items":["How far did the work get? Count delivered drafts and checked-off checklist items, not hours.","What can you keep using? Drafts and files you will build on are value received.","Whose change of plan was it? An ending caused by the client''s change of direction deserves a more generous tier.","What did the stage cost the freelancer in time they could have sold elsewhere?"]},{"type":"p","content":"Say which tier you intend in the stage''s room before you confirm it. The preview makes the numbers transparent; a sentence of reasoning makes the decision feel like a conversation rather than a verdict."}]},{"id":"other-ways-work-ends","heading":"Other ways work ends","body":[{"type":"p","content":"A Fair Exit is the deliberate ending. The platform has fixed rules for the others:"},{"type":"dl","items":[{"term":"A parked claim","definition":"A ticket claimed but never started expires after its time limit (24 hours by default). It returns to the backlog, any escrow held is refunded to the client in full, and the freelancer is paid nothing."},{"term":"Removal mid-ticket","definition":"If a freelancer is removed from a stage while holding a claimed ticket, that ticket''s escrow is released to them in full and the ticket returns to the backlog for someone else."},{"term":"A deleted ticket","definition":"Deleting a ticket before it is claimed pays nobody; if the client prepaid it, the escrow comes back to them in full. Deleting one after it is claimed releases its escrow to the freelancer in full."},{"term":"A cancelled session","definition":"Cancelled by the client more than 24 hours ahead: refunded. Inside 24 hours: paid to the freelancer for the time they reserved. Cancelled by the freelancer: refunded in full, at any time."}]}]},{"id":"when-you-disagree","heading":"When you disagree","body":[{"type":"p","content":"For a session, disagreement has a defined path. An attendee who reports a no-show opens a dispute, and the sitting''s payment stays held while it runs. The conferencing logs are checked first: if the provider never joined, the attendee is refunded; if both were present for most of the session, the claim is dismissed. When the logs cannot settle it, the provider has 48 hours to respond before the case goes to a Projective reviewer, who can release the payment, refund it or split it."},{"type":"quote","content":"A dispute is never deleted, and a ruling is final: the record of what happened stays with the work."},{"type":"p","content":"For a deliverable stage, the honest first step is the stage''s own room. Most disagreements about a stage are disagreements about its checklist, and most of those end in a revision or a Fair Exit both sides can live with."}]},{"id":"ending-well","heading":"Ending well","body":[{"type":"list","ordered":true,"items":["Decide early. A stage ended at a quarter of the way through costs everyone less than one ended at the deadline.","Explain the tier in the stage''s room before you confirm it.","Agree in writing what happens to the drafts already delivered.","If the relationship is sound, say so — the next stage can start the same day."]},{"type":"p","content":["Ending a stage fairly depends on the money having been held properly from the start. ",{"type":"link","href":"/articles/no-hold-no-work","text":"No hold, no work"}," explains how."]}]}]'::jsonb, '/test_images/banner_2.jpg', 'A silver sports car photographed in motion, the street behind it blurred', 1280, 720, 'projective-editorial', 'published', '2026-10-14T08:00:00Z'::timestamptz, '2026-10-14T08:00:00Z'::timestamptz, '{}'::text[])
